# Presupuesto ilustrativo de latencia: mide requisitos, no proveedores.
alternativas = {"local": (300, 1), "lotes": (60, 2), "eventos": (2, 4)}
latencia_max_s = 120
viables = {k:v for k,v in alternativas.items() if v[0] <= latencia_max_s}
seleccion = min(viables, key=lambda k: viables[k][1]) if viables else 'NINGUNA'
print(seleccion, viables)

